// lunae · Raport dzienny — date ranges (Europe/Warsaw calendar days, converted to UTC for WooCommerce).
// Optional manual override: input item may carry report_date = 'yyyy-MM-dd' (the day to report on).
const tz = 'Europe/Warsaw';
const input = $input.first() ? $input.first().json : {};
const override = input && typeof input.report_date === 'string' && /^\d{4}-\d\d-\d\d$/.test(input.report_date) ? input.report_date : null;
const today = override
  ? DateTime.fromISO(override, { zone: tz }).plus({ days: 1 }).startOf('day')
  : DateTime.now().setZone(tz).startOf('day');
const y = today.minus({ days: 1 });
const monthStart = y.startOf('month');
const wStart = y.minus({ days: 7 });
const fetchFrom = monthStart < wStart ? monthStart : wStart;
const u = function (d) { return d.toUTC().toFormat("yyyy-MM-dd'T'HH:mm:ss"); };

return [{
  json: {
    tz: tz,
    y_date: y.toISODate(),
    y_label: y.setLocale('pl').toFormat('cccc, d MMMM yyyy'),
    y_short: y.toFormat('d.MM'),
    w_date: wStart.toISODate(),
    w_label: wStart.setLocale('pl').toFormat('ccc d.MM'),
    month_start_date: monthStart.toISODate(),
    month_label: y.setLocale('pl').toFormat('LLLL'),
    fetch_from_date: fetchFrom.toISODate(),
    y_start_utc: u(y),
    y_end_utc: u(today),
    w_start_utc: u(wStart),
    w_end_utc: u(wStart.plus({ days: 1 })),
    month_start_utc: u(monthStart),
    fetch_from_utc: u(fetchFrom),
  },
}];

// lunae · Raport dzienny — build one Discord embed from Woo orders/refunds + Meta insights.
// Meta / refunds failures are tolerated (report still posts with "brak danych").
const CAMPAIGN_CAP_FALLBACK = 1500; // zł, used only when Meta does not return spend_cap
const PAID = ['processing', 'completed', 'refunded'];
const ctx = $('Zakresy dat').first().json;

function safeAll(name) { try { return $(name).all(); } catch (e) { return []; } }
function ms(s) { return Date.parse(s + 'Z'); }
function gmt(s) {
  if (!s) return null;
  const str = String(s);
  const v = Date.parse(/Z$|[+-]\d\d:\d\d$/.test(str) ? str : str + 'Z');
  return isNaN(v) ? null : v;
}
function grp(intStr) { return intStr.replace(/\B(?=(\d{3})+(?!\d))/g, ' '); }
function money(v) {
  const n = Number(v) || 0;
  const p = Math.abs(n).toFixed(2).split('.');
  return (n < 0 ? '-' : '') + grp(p[0]) + ',' + p[1] + ' zł';
}
function int(v) { return grp(String(Math.round(Number(v) || 0))); }
function dec(v, d) { return (Number(v) || 0).toFixed(d).replace('.', ','); }
function errText(e) {
  if (!e) return 'nieznany błąd';
  if (typeof e === 'string') return e.slice(0, 120);
  return String(e.message || e.description || e.error_user_msg || JSON.stringify(e)).slice(0, 120);
}
function itemName(li) {
  let name = String(li.name || 'Produkt').trim();
  const extras = [];
  for (const m of (li.meta_data || [])) {
    if (!m || typeof m.key !== 'string' || m.key.charAt(0) === '_') continue;
    const raw = m.display_value != null ? m.display_value : m.value;
    if (typeof raw !== 'string' && typeof raw !== 'number') continue;
    const clean = String(raw).replace(/<[^>]*>/g, '').trim();
    if (clean && clean.length <= 40 && name.indexOf(clean) === -1) extras.push(clean);
  }
  return extras.length ? name + ' – ' + extras.join(', ') : name;
}
function delta(cur, prev, fmt) {
  if (prev === null || prev === undefined) return '';
  const d = cur - prev;
  const arrow = d > 0 ? '↑' : (d < 0 ? '↓' : '→');
  return arrow + ' tydz. temu: ' + fmt(prev);
}

// ---------- WooCommerce orders ----------
const seen = {};
const orders = [];
for (const it of safeAll('Pobierz zamówienia (Woo)')) {
  const o = it.json || {};
  if (!o.id || !o.status || seen[o.id]) continue;
  seen[o.id] = true;
  orders.push(o);
}
function stats(from, to) {
  const inR = orders.filter(function (o) { const c = gmt(o.date_created_gmt); return c !== null && c >= from && c < to; });
  const paid = inR.filter(function (o) { return PAID.indexOf(o.status) !== -1; });
  const count = function (st) { return inR.filter(function (o) { return o.status === st; }).length; };
  const revenue = paid.reduce(function (s, o) { return s + (Number(o.total) || 0); }, 0);
  const units = paid.reduce(function (s, o) {
    return s + (o.line_items || []).reduce(function (a, li) { return a + (Number(li.quantity) || 0); }, 0);
  }, 0);
  return { paid: paid, orders: paid.length, revenue: revenue, units: units,
    failed: count('failed'), pending: count('pending'), onhold: count('on-hold'), cancelled: count('cancelled') };
}
const Y0 = ms(ctx.y_start_utc), Y1 = ms(ctx.y_end_utc);
const W0 = ms(ctx.w_start_utc), W1 = ms(ctx.w_end_utc);
const M0 = ms(ctx.month_start_utc);
const sy = stats(Y0, Y1);
const sw = stats(W0, W1);
const sm = stats(M0, Y1);

const prod = {};
for (const o of sy.paid) {
  for (const li of (o.line_items || [])) {
    const k = itemName(li);
    if (!prod[k]) prod[k] = { qty: 0, value: 0 };
    prod[k].qty += Number(li.quantity) || 0;
    prod[k].value += (Number(li.total) || 0) + (Number(li.total_tax) || 0);
  }
}
const top = Object.keys(prod).map(function (k) { return { name: k, qty: prod[k].qty, value: prod[k].value }; })
  .sort(function (a, b) { return b.qty - a.qty || b.value - a.value; }).slice(0, 5);
let topText = top.map(function (p, i) { return (i + 1) + '. ' + p.name + ' × ' + p.qty + ' (' + money(p.value) + ')'; }).join('\n');
if (!topText) topText = '—';
if (topText.length > 1000) topText = topText.slice(0, 999) + '…';

// ---------- Refunds ----------
const refItems = safeAll('Pobierz zwroty (Woo)');
let refundsText;
if (refItems.length && refItems[0].json && refItems[0].json.error) {
  refundsText = 'brak danych';
} else {
  const refs = refItems.map(function (i) { return i.json || {}; }).filter(function (r) { return r.id; });
  const inRange = function (from, to) {
    return refs.filter(function (r) { const c = gmt(r.date_created_gmt); return c !== null && c >= from && c < to; });
  };
  const sum = function (arr) { return arr.reduce(function (s, r) { return s + Math.abs(Number(r.amount) || 0); }, 0); };
  const ry = inRange(Y0, Y1), rm = inRange(M0, Y1);
  refundsText = (ry.length ? ry.length + ' · ' + money(sum(ry)) : '0') + '\nMTD: ' + (rm.length ? rm.length + ' · ' + money(sum(rm)) : '0');
}

// ---------- Meta: account daily insights ----------
const PURCHASE_TYPES = ['omni_purchase', 'purchase', 'offsite_conversion.fb_pixel_purchase'];
function pick(list) {
  if (!Array.isArray(list)) return 0;
  for (const t of PURCHASE_TYPES) {
    const a = list.find(function (x) { return x && x.action_type === t; });
    if (a) return Number(a.value) || 0;
  }
  return 0;
}
let metaErr = null;
let rows = [];
const mItem = safeAll('Meta · konto dziennie')[0];
if (!mItem || !mItem.json) metaErr = 'brak odpowiedzi';
else if (mItem.json.error) metaErr = errText(mItem.json.error);
else if (!Array.isArray(mItem.json.data)) metaErr = 'nieoczekiwana odpowiedź API';
else rows = mItem.json.data;

function metaAgg(fromDate, toDate) {
  const r = rows.filter(function (x) { return x.date_start >= fromDate && x.date_start <= toDate; });
  return r.reduce(function (a, x) {
    a.spend += Number(x.spend) || 0;
    a.impressions += Number(x.impressions) || 0;
    a.clicks += Number(x.inline_link_clicks) || 0;
    a.purchases += pick(x.actions);
    a.purchaseValue += pick(x.action_values);
    return a;
  }, { spend: 0, impressions: 0, clicks: 0, purchases: 0, purchaseValue: 0 });
}
const my = metaErr ? null : metaAgg(ctx.y_date, ctx.y_date);
const mw = metaErr ? null : metaAgg(ctx.w_date, ctx.w_date);
const mm = metaErr ? null : metaAgg(ctx.month_start_date, ctx.y_date);

// ---------- Meta: campaign cap ----------
let campaignText = null;
const cItem = safeAll('Meta · kampania Evergreen')[0];
if (cItem && cItem.json && !cItem.json.error && (cItem.json.id || cItem.json.name)) {
  const c = cItem.json;
  const lifetime = c.insights && Array.isArray(c.insights.data) && c.insights.data[0] ? Number(c.insights.data[0].spend) || 0 : 0;
  const rawCap = Number(c.spend_cap);
  let cap = CAMPAIGN_CAP_FALLBACK;
  let capNote = ' (limit z konfiguracji)';
  if (rawCap > 0 && rawCap < 922337203685478) { cap = rawCap / 100; capNote = ''; }
  const pct = cap > 0 ? Math.round(lifetime / cap * 100) : 0;
  const daily = Number(c.daily_budget) > 0 ? ' · ' + money(Number(c.daily_budget) / 100) + '/dzień' : '';
  campaignText = money(lifetime) + ' / ' + money(cap) + ' (' + pct + '%)' + capNote + ' · ' + (c.effective_status || '?') + daily;
} else if (cItem && cItem.json && cItem.json.error) {
  campaignText = 'brak danych (' + errText(cItem.json.error) + ')';
}

// ---------- Computed ----------
function roas(rev, spend) { return spend > 0 ? dec(rev / spend, 2) + '×' : '—'; }
function cpo(spend, n) {
  if (!(spend > 0)) return '—';
  return n > 0 ? money(spend / n) : 'brak zamówień';
}

// ---------- Embed ----------
const fields = [];
fields.push({ name: 'Zamówienia opłacone', value: String(sy.orders) + '\n' + delta(sy.orders, sw.orders, String), inline: true });
fields.push({ name: 'Przychód brutto', value: money(sy.revenue) + '\n' + delta(sy.revenue, sw.revenue, money), inline: true });
fields.push({ name: 'Śr. koszyk', value: sy.orders ? money(sy.revenue / sy.orders) : '—', inline: true });
fields.push({ name: 'Sprzedane sztuki', value: int(sy.units), inline: true });
fields.push({ name: 'Nieopłacone / nieudane', value: 'oczekujące ' + sy.pending + ' · on-hold ' + sy.onhold + '\nnieudane ' + sy.failed + ' · anulowane ' + sy.cancelled, inline: true });
fields.push({ name: 'Zwroty', value: refundsText, inline: true });
fields.push({ name: 'Top produkty (wczoraj)', value: topText, inline: false });

if (metaErr) {
  fields.push({ name: 'Meta Ads', value: 'Meta: brak danych (' + metaErr + ')', inline: false });
} else {
  const ctr = my.impressions > 0 ? dec(my.clicks / my.impressions * 100, 2) + '%' : '—';
  fields.push({ name: 'Meta Ads · wczoraj', value:
    'Wydatki ' + money(my.spend) + ' · wyśw. ' + int(my.impressions) + ' · kliknięcia w link ' + int(my.clicks) + ' (CTR ' + ctr + ')\n' +
    'Zakupy wg Meta: ' + int(my.purchases) + ' · ' + money(my.purchaseValue) +
    (mw ? '\nTydz. temu: wydatki ' + money(mw.spend) : ''), inline: false });
  fields.push({ name: 'ROAS (Woo ÷ Meta)', value: 'wczoraj ' + roas(sy.revenue, my.spend) + '\nMTD ' + roas(sm.revenue, mm.spend), inline: true });
  fields.push({ name: 'Koszt / zamówienie', value: 'wczoraj ' + cpo(my.spend, sy.orders) + '\nMTD ' + cpo(mm.spend, sm.orders), inline: true });
}
fields.push({ name: 'Miesiąc do wczoraj (' + ctx.month_label + ')', value:
  sm.orders + ' zam. · ' + money(sm.revenue) + (sm.orders ? ' · śr. ' + money(sm.revenue / sm.orders) : '') +
  (mm ? '\nMeta: ' + money(mm.spend) + ' · zakupy wg Meta ' + int(mm.purchases) + ' (' + money(mm.purchaseValue) + ')' : '\nMeta: brak danych'), inline: false });
if (campaignText) fields.push({ name: 'Kampania Evergreen (wydane / limit)', value: campaignText, inline: false });

for (const f of fields) {
  f.value = String(f.value || '—').trim() || '—';
  if (f.value.length > 1024) f.value = f.value.slice(0, 1023) + '…';
}

const embed = {
  title: 'Raport dzienny · ' + ctx.y_label,
  color: metaErr ? 0xE67E22 : (sy.orders > 0 ? 0x2ECC71 : 0x95A5A6),
  fields: fields,
  footer: { text: 'Woo: zamówienia wg daty utworzenia (Europe/Warsaw), brutto · opłacone = processing/completed/refunded · porównanie: ' + ctx.w_label },
  timestamp: new Date().toISOString(),
};
const content = '📊 Raport ' + ctx.y_short + ': ' + sy.orders + ' zam. · ' + money(sy.revenue) +
  (my ? ' · Meta ' + money(my.spend) + ' · ROAS ' + roas(sy.revenue, my.spend) : ' · Meta: brak danych');

return [{ json: { content: content, embed_json: JSON.stringify(embed), meta_ok: !metaErr, orders_yesterday: sy.orders, revenue_yesterday: Math.round(sy.revenue * 100) / 100 } }];
